    ('S3-V016', 41, 11561, 'b0cdab84ee6972e23f28d1a86ff5ec0d', 'zahl', 'negativ', null, $rbf${"wert": -96, "einheit": "Punkte"}$rbf$::jsonb, 'rr.potenz', $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "96", "text": "das Minus vergessen: 3 · 32", "fehlbild": null, "regel": null}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "-30", "text": "„hoch 5“ als „mal 5“ gerechnet: 3 · (−2) · 5", "fehlbild": null, "regel": null}, {"nr": 3, "art": "zahl", "luecke": null, "wert": "-32", "text": "den Startwert 3 vergessen", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('S3-V008', 44, 11891, '38c59929f6bb427ec4a333fce5640efe', 'auswahl', 'klammern', '59329945b84475955ce27320a75f016c', $rbf${"index": 2}$rbf$::jsonb, 'rr.reihenfolge', $rbf$[{"nr": 1, "art": "index", "luecke": null, "wert": "0", "text": "ohne Klammern gerechnet: Punkt vor Strich ergibt 20 + 30 − 3", "fehlbild": null, "regel": null}, {"nr": 2, "art": "index", "luecke": null, "wert": "1", "text": "nur die ersten beiden Schritte geklammert, das Teilen durch 5 trifft dann nur die 15", "fehlbild": null, "regel": null}, {"nr": 3, "art": "index", "luecke": null, "wert": "3", "text": "die Klammer um die falschen Schritte gesetzt", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('S3-V009', 44, 11892, '45f8a9fb6d1924cb4b44dcd60eb1bdbd', 'zahl', 'vorteil', null, $rbf${"wert": 23}$rbf$::jsonb, 'rr.tauschen', $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "575", "text": "nur das Malnehmen mit 4 rückgängig gemacht", "fehlbild": null, "regel": null}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "92", "text": "nur das Malnehmen mit 25 rückgängig gemacht", "fehlbild": null, "regel": null}, {"nr": 3, "art": "zahl", "luecke": null, "wert": "2300", "text": "nur das Addieren von 17 rückgängig gemacht", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('S3-V010', 44, 11893, '6aaa1f6b704f64649731d122d7996971', 'auswahl', 'verteilen', '6cb911a71d07c5765726ebd2cb6fd197', $rbf${"index": 1}$rbf$::jsonb, null, $rbf$[{"nr": 1, "art": "index", "luecke": null, "wert": "0", "text": "diese Zeile ist richtig; der erste Fehler steckt in Zeile 2", "fehlbild": null, "regel": null}, {"nr": 2, "art": "index", "luecke": null, "wert": "2", "text": "diese Zeile folgt aus der falschen Zeile 2 richtig; der erste Fehler steckt weiter oben", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('S3-V011', 44, 11894, '8e15e2e212ad09b92d2f3fa3d94024b9', 'zahl', 'mal_ganz', null, $rbf${"wert": -6, "einheit": "m"}$rbf$::jsonb, 'rr.vorzeichen', $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "-46", "text": "die Vergangenheit wie die Zukunft gerechnet (5 Minuten später)", "fehlbild": null, "regel": null}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "-30", "text": "nur eine Minute gerechnet, und zwar vorwärts statt zurück: −26 + (−4)", "fehlbild": null, "regel": null}, {"nr": 3, "art": "zahl", "luecke": null, "wert": "6", "text": "beide Vorzeichen umgekehrt: statt −26 + 20 gerechnet 26 − 20", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('S3-V012', 44, 11895, '128c50a5ab976bb3da189993e1984cce', 'zahl', 'umkehraufgabe_mal', null, $rbf${"wert": 3}$rbf$::jsonb, 'rr.gegenrechnung', $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "8", "text": "das Abziehen von 15 falsch rückgängig gemacht (noch einmal abgezogen)", "fehlbild": null, "regel": null}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "-3", "text": "beim letzten Schritt das Vorzeichen von −6 vergessen", "fehlbild": null, "regel": null}, {"nr": 3, "art": "zahl", "luecke": null, "wert": "-18", "text": "den Faktor (−6) nicht rückgängig gemacht", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('S3-V013', 44, 11896, 'f1336f42c9cf5fa09771779df19ac436', 'zahl', 'schriftlich', null, $rbf${"wert": 180}$rbf$::jsonb, null, $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "1380", "text": "die ganze erste Zeile genannt statt des einen Feldes", "fehlbild": null, "regel": null}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "2580", "text": "1 200 zu 1 380 dazugezählt statt abgezogen", "fehlbild": null, "regel": null}, {"nr": 3, "art": "zahl", "luecke": null, "wert": "1060", "text": "ein Feld der rechten Spalte (320) statt des Feldes 1 200 abgezogen", "fehlbild": null, "regel": null}]$rbf$::jsonb)
  ) x(k, e, r, mt, y, l, ma, o, regel, fb) loop
    select count(*) into n from schule.aufgabe where einheit_id = z.e and pool = 'uebung' and reihenfolge = z.r;
    if n <> 1 then fehler := fehler || format('%s: %s Übungsaufgaben an Einheit %s, Platz %s', z.k, n, z.e, z.r); continue; end if;
    select * into a from schule.aufgabe where einheit_id = z.e and pool = 'uebung' and reihenfolge = z.r;
    if md5(coalesce(a.frage->>'text', '')) <> z.mt or a.antworttyp is distinct from z.y or a.variante_gruppe is distinct from z.l
       or (z.ma is not null and md5(coalesce((select string_agg(t.x, E'\n' order by t.o) from jsonb_array_elements_text(a.antworten) with ordinality t(x, o)), '')) <> z.ma) then
      fehler := fehler || format('%s: Aufgabe %s (Einheit %s, Platz %s) ist nicht die erwartete (Fragetext/Typ/Lernkarte/Antworten)', z.k, a.id, z.e, z.r); continue; end if;
    -- Lösung samt Einheit und Toleranz wie eingespielt (jsonb-Gleichheit: Zahlen werden als Zahlen verglichen, 12 = 12.0)
    if a.loesung is distinct from z.o then
      fehler := fehler || format('%s: Aufgabe %s (Einheit %s, Platz %s): Lösung %s statt %s wie eingespielt', z.k, a.id, z.e, z.r, a.loesung, z.o); continue; end if;
    if a.id = any(v_ids) then fehler := fehler || format('%s: Aufgabe %s doppelt zugeordnet', z.k, a.id); continue; end if;
    v_ids := v_ids || a.id;
    if z.regel is not null then
      insert into schule.aufgabe_regel (aufgabe_id, regel) values (a.id, z.regel) on conflict do nothing;
      get diagnostics c = row_count; n_regel_neu := n_regel_neu + c;
      if (select r.regel from schule.aufgabe_regel r where r.aufgabe_id = a.id) is distinct from z.regel then
        fehler := fehler || format('%s: Aufgabe %s hat schon eine andere Regel', z.k, a.id); end if;
    end if;
    for f in select * from jsonb_array_elements(z.fb) loop
      insert into schule.aufgabe_fehlbild (aufgabe_id, nr, art, luecke, wert, beschreibung, fehlbild, regel)
      values (a.id, (f->>'nr')::smallint, f->>'art', (f->>'luecke')::smallint, f->>'wert', f->>'text', f->>'fehlbild', f->>'regel') on conflict do nothing;
      get diagnostics c = row_count; n_fb_neu := n_fb_neu + c;
      select * into v_alt from schule.aufgabe_fehlbild x where x.aufgabe_id = a.id and x.nr = (f->>'nr')::smallint;
      if v_alt.nr is null or (v_alt.art, v_alt.luecke, v_alt.wert, v_alt.beschreibung, v_alt.fehlbild, v_alt.regel)
           is distinct from (f->>'art', (f->>'luecke')::smallint, f->>'wert', f->>'text', f->>'fehlbild', f->>'regel') then
        fehler := fehler || format('%s: Fehlbild %s steht schon anders da (oder gleicher Schlüssel unter anderer Nummer)', z.k, f->>'nr'); continue; end if;
      v := schule.fehlbild_probeantwort(a, f->>'art', (f->>'luecke')::int, f->>'wert');
      b := schule.antwort_bewerten(a, v);
      if not coalesce((b->>'format_ok')::boolean, false) or coalesce((b->>'richtig')::boolean, true) then
        fehler := fehler || format('%s: Fehlbild %s – Antwort %s wird nicht als gültig und falsch bewertet (%s)', z.k, f->>'nr', v, b); continue; end if;
      if schule.fehlbild_finden(a, v) is distinct from (f->>'nr')::smallint then
        fehler := fehler || format('%s: Fehlbild %s wird an der Antwort %s nicht wiedererkannt', z.k, f->>'nr', v); end if;
    end loop;
    if (select count(*) from schule.aufgabe_fehlbild x where x.aufgabe_id = a.id) <> jsonb_array_length(z.fb) then
      fehler := fehler || format('%s: Aufgabe %s hat andere Fehlbilder in der Datenbank als im Paket', z.k, a.id); end if;
  end loop;
  if array_length(fehler, 1) > 0 then raise exception 'RB-S Regelbezug ABBRUCH, alles zurückgerollt (% Befunde): %', array_length(fehler, 1), array_to_string(fehler[1:40], ' | '); end if;
  if coalesce(array_length(v_ids, 1), 0) <> 60
     or (select count(*) from schule.aufgabe_regel where aufgabe_id = any(v_ids)) <> 42
     or (select count(*) from schule.aufgabe_fehlbild where aufgabe_id = any(v_ids)) <> 170 then
    raise exception 'RB-S Regelbezug ABBRUCH: Zählung stimmt nicht (Aufgaben %, erwartet 60)', array_length(v_ids, 1); end if;
  raise notice 'RB-S Regelbezug: % Aufgaben, % Regeln neu, % Fehlbilder neu (zweiter Lauf: 0 und 0)', array_length(v_ids, 1), n_regel_neu, n_fb_neu;
end $rbnach$;
